INSERT INTO area_content (area_id, content_key, content_ar, content_en, content_fr, content_type, section, sort_order) SELECT id, 'seo_description', 'حصص فردية أونلاين لتحفيظ القرآن وتأسيس اللغة العربية للأطفال والشباب والبالغين من الناطقين بالعربية في سيدني وملبورن وبريزبن وباقي مدن أستراليا، مع أول حصة تجريبية مجانية ومواعيد مرنة وخصم خاص للأخوة.', 'حصص فردية أونلاين لتحفيظ القرآن وتأسيس اللغة العربية للأطفال والشباب والبالغين من الناطقين بالعربية في سيدني وملبورن وبريزبن وباقي مدن أستراليا، مع أول حصة تجريبية مجانية ومواعيد مرنة وخصم خاص للأخوة.', NULL, 'text', 'seo', 1 FROM site_areas WHERE slug='australia' ON CONFLICT (area_id, content_key) DO UPDATE SET content_ar=EXCLUDED.content_ar, updated_at=NOW();
