INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, answer_ar, answer_en, sort_order) SELECT id, 'australia-faq-1', 'هل تناسب الحصص الأطفال المقيمين في أستراليا؟', 'هل تناسب الحصص الأطفال المقيمين في أستراليا؟', 'نعم، الحصص الفردية مناسبة للأطفال والشباب والبالغين من الناطقين بالعربية، مع خطة تناسب مستوى الطالب.', 'نعم، الحصص الفردية مناسبة للأطفال والشباب والبالغين من الناطقين بالعربية، مع خطة تناسب مستوى الطالب.', 0 FROM site_areas WHERE slug='australia' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, answer_ar, answer_en, sort_order) SELECT id, 'australia-faq-2', 'كيف نختار الموعد المناسب مع اختلاف التوقيت؟', 'كيف نختار الموعد المناسب مع اختلاف التوقيت؟', 'ننسق مع الأسرة لاختيار وقت مناسب بتوقيت سيدني أو مدينتكم، مع مراعاة توافر المعلم والطالب.', 'ننسق مع الأسرة لاختيار وقت مناسب بتوقيت سيدني أو مدينتكم، مع مراعاة توافر المعلم والطالب.', 1 FROM site_areas WHERE slug='australia' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, answer_ar, answer_en, sort_order) SELECT id, 'australia-faq-3', 'هل أول حصة تجريبية مجانية؟', 'هل أول حصة تجريبية مجانية؟', 'نعم، أول حصة تجريبية مجانية للتعرف على مستوى الطالب واحتياجه قبل اختيار الباقة.', 'نعم، أول حصة تجريبية مجانية للتعرف على مستوى الطالب واحتياجه قبل اختيار الباقة.', 2 FROM site_areas WHERE slug='australia' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, answer_ar, answer_en, sort_order) SELECT id, 'australia-faq-4', 'هل يوجد خصم للأخوة؟', 'هل يوجد خصم للأخوة؟', 'نعم، يوجد خصم خاص للأخوة، ويمكن معرفة التفاصيل عند التواصل عبر واتساب.', 'نعم، يوجد خصم خاص للأخوة، ويمكن معرفة التفاصيل عند التواصل عبر واتساب.', 3 FROM site_areas WHERE slug='australia' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
